"""Publish an original Pact generated by a BFF consumer test."""

import argparse
import base64
import hashlib
import json
import os
from pathlib import Path

from registry import Registry

REPOSITORY = "https://github.com/MichalBoczula/ECommerceStoreBFF"


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("artifact", type=Path)
    parser.add_argument("receipt", type=Path)
    parser.add_argument("--provider", choices=("users", "invoice"), default="users")
    args = parser.parse_args()
    ref = os.environ["GITHUB_REF"]
    if os.environ["GITHUB_EVENT_NAME"] not in ("push", "workflow_dispatch") or ref != "refs/heads/master":
        raise ValueError("Consumer Pact publication requires a push or manual run on BFF master.")

    provider = args.provider
    pact_file = f"bff-{provider}.json"
    manifest = json.loads((args.artifact / "manifest.json").read_bytes())
    content = (args.artifact / pact_file).read_bytes()
    pact = json.loads(content)
    digest = hashlib.sha256(content).hexdigest()
    if (
        manifest["schemaVersion"] != 1 or manifest["file"] != pact_file or manifest["sha256"] != digest
        or (manifest["consumer"], manifest["provider"]) != ("bff", provider)
        or (pact["consumer"]["name"], pact["provider"]["name"]) != ("bff", provider)
        or manifest["pactSpecification"] != "4.0" or pact["metadata"]["pactSpecification"]["version"] != "4.0"
        or manifest["interactionCount"] != len(pact["interactions"]) or not pact["interactions"]
    ):
        raise ValueError("Artifact bytes or Pact identity differ from the BFF manifest.")

    sha = os.environ["GITHUB_SHA"]
    build_url = f"{REPOSITORY}/actions/runs/{os.environ['GITHUB_RUN_ID']}"
    call = Registry().call
    call("/api/applications/bff/versions", {"commitSha": sha, "repositoryUrl": REPOSITORY})
    call("/api/integrations", {"consumerApplicationId": "bff", "providerApplicationId": provider})
    publication = call("/api/contract-publications", {
        "sourceApplicationId": "bff", "commitSha": sha, "kind": "ConsumerPact",
        "consumerApplicationId": "bff", "providerApplicationId": provider,
        "sourceRef": ref, "buildUrl": build_url, "contentBase64": base64.b64encode(content).decode("ascii"),
    })
    if publication["artifactSha256"] != digest:
        raise RuntimeError("The registry returned a different contract hash.")
    args.receipt.write_text(json.dumps({
        "publicationId": publication["id"], "commitSha": sha, "sha256": digest, "buildUrl": build_url,
    }, indent=2) + "\n", encoding="utf-8")
    print(f"Published BFF → {provider} Pact {digest} as {publication['id']}.")


if __name__ == "__main__":
    main()
